/* SOVEREIGN global modules (1–12): economies, equities, currencies, commodities, fiscal, trade, flows, corporates,
   credit, relationship engine, global dashboard, coverage. Data: data/global.json (built daily by finintel/global_build.py). */
"use strict";
const GD = () => S.G;
const CTRY = () => (S.G && S.G.countries) || [];
const cBy = k => CTRY().find(c => c.key === k);
const big = (v, cur = "$") => v == null ? "—" : Math.abs(v) >= 1e12 ? `${cur}${fmt(v / 1e12, 2)}tn` : Math.abs(v) >= 1e9 ? `${cur}${fmt(v / 1e9, 1)}bn` : Math.abs(v) >= 1e6 ? `${cur}${fmt(v / 1e6, 0)}m` : `${cur}${fmt(v, 0)}`;
const wbL = (code, iso) => GD()?.wb?.[code]?.[iso]?.latest || null;
const IMF_WB = { NGDP_RPCH: "NY.GDP.MKTP.KD.ZG", PCPIPCH: "FP.CPI.TOTL.ZG", LUR: "SL.UEM.TOTL.ZS", NGDPDPC: "NY.GDP.PCAP.CD" };
/** IMF WEO latest value; falls back to the World Bank equivalent (labelled) when IMF data is unavailable. */
const imfL = (code, iso) => { const v = GD()?.imf?.[code]?.[iso]?.latest; if (v) return v;
  if (IMF_WB[code]) { const w = wbL(IMF_WB[code], iso); if (w) return { value: w.value, year: w.year, kind: "Actual (World Bank)" }; }
  if (code === "BCA_NGDPD") { const ca = wbL("BN.CAB.XOKA.CD", iso), gdp = wbL("NY.GDP.MKTP.CD", iso); if (ca && gdp && ca.year === gdp.year) return { value: ca.value / gdp.value * 100, year: ca.year, kind: "Derived (World Bank)" }; }
  return null; };
const imfSer = (code, iso) => { const v = GD()?.imf?.[code]?.[iso]; if (v) return v; const w = IMF_WB[code] && GD()?.wb?.[IMF_WB[code]]?.[iso]; return w ? { series: { ...w.series, kinds: w.series.years.map(() => "Actual (World Bank)") } } : null; };
const L = (arr, empty) => listOr((arr || []).map(h => new String(h)), empty);
const PXY = t => { const p = (GD().proxied || {})[t]; return p ? ` <span class="pill warn" title="The index feed failed; this row uses ${esc(p.name)} (${esc(p.ticker)}), a fund that tracks it. Price level is the fund's, not the index's.">proxy: ${esc(p.ticker)}</span>` : ""; };
const PEND = `<span class="pill warn">Pending source</span>`;
function needGlobal(pg) { return header(pg) + `<div class="pending"><b>Global data file not built yet.</b> The daily run writes data/global.json; it appears after the next successful GitHub Actions run.</div>`; }
const G_ = fn => pg => GD() ? fn(pg) : needGlobal(pg);

/* ---------------- metadata (Module 12) ---------------- */
const SRCPFX = { yahoo: "yahoo", worldbank: "wb", imf: "imf", bis: "bis", comtrade: "comtrade", sec: "sec", cftc: "cftc", fred: "fred", positions: "positions" };
const SRCSEC = { positions: "positions", worldbank: "wb", imf: "imf", bis: "rates", comtrade: "trade", sec: "companies", cftc: "cftc_fx" };
function metaStrip(keys, extra = {}) {
  const g = GD(); if (!g) return "";
  const rows = keys.map(k => { const m = g.meta[k] || {}; const pfx = SRCPFX[k]; const errs = Object.keys(g.errors || {}).filter(e => e.startsWith(pfx + ":")).length;
    const rev = (g.revisions || {})[pfx] || 0, ex = extra[k] || {}, secn = SRCSEC[k], car = secn && (g.carried || {})[secn], fet = secn && (g.fetched || {})[secn];
    return [`<a href="${esc(m.url)}" target="_blank" rel="noopener">${esc(m.provider)}</a><div class="sm dim">${esc(m.source)}</div>`, esc(ex.observation || m.observation || "see each value"), esc(m.published || ex.published || "—"), esc(ex.period || m.period || "—"), esc(m.frequency), esc(m.kind), statusPill(m.confidence === "High" ? "High" : "Medium").replace(/>(High|Medium)</, `>${esc(m.confidence || "—")}<`), (car ? statusPill("Fair").replace(">Fair<", `>Carried forward from ${esc(car.from || "previous run")}${car.keys !== "all" ? ` (${car.keys.length} series)` : ""}<`) : errs ? statusPill("Fair").replace(">Fair<", `>${errs} feed(s) failed<`) : statusPill("Good").replace(">Good<", ">Loaded<")) + (fet ? `<div class="sm dim">refreshed ${esc(fet)}${g.refresh_days?.[secn] ? `, every ${g.refresh_days[secn]} days` : ""}</div>` : ""), `<span class="num">${rev}</span>`]; });
  return `<details class="p" style="margin-bottom:12px"><summary class="p-h" style="cursor:pointer;list-style:none"><h2>Data sources and status</h2><span class="meta">${keys.map(k => esc(g.meta[k]?.provider || k)).join(" · ")} — click to expand</span></summary><div class="p-b flush">` +
    table([{ t: "Provider / source" }, { t: "Observation" }, { t: "Published / updated" }, { t: "Reporting period" }, { t: "Frequency" }, { t: "Actual or estimated" }, { t: "Confidence" }, { t: "Status" }, { t: "Revisions recorded", n: 1 }], rows) +
    `<div class="note" style="padding:0 14px 10px">Revisions = values that changed after first being stored (point-in-time database). Missing values are shown as "—" or "pending", never as zero.</div></div></details>`;
}
/** one indicator row: label, value, period, kind, source, status */
function indRow(label, v, unit, period, kind, source, isMoney) {
  if (kind && kind.includes("World Bank")) source = "World Bank (IMF unavailable)";
  if (v == null) return [esc(label), `<span class="dim">—</span>`, "", "", esc(source || ""), PEND];
  const val = isMoney ? big(v) : `${fmt(v, Math.abs(v) >= 100 ? 0 : 2)}${unit || ""}`;
  return [esc(label), `<b class="num">${val}</b>`, `<span class="num sm">${esc(period ?? "")}</span>`, `<span class="sm">${esc(kind || "Actual")}</span>`, `<span class="sm dim">${esc(source)}</span>`, statusPill("Good").replace(">Good<", ">Available<")];
}
const IND_COLS = [{ t: "Indicator" }, { t: "Latest", n: 1 }, { t: "Period" }, { t: "Actual / estimate" }, { t: "Source" }, { t: "Status" }];
function yrSeries(d, name, color) { if (!d) return []; const s = d.series; const kinds = s.kinds || s.years.map(() => "Actual");
  const act = { name, dates: [], values: [], color }, pro = { name: name + " (IMF projection)", dates: [], values: [], color, dash: "4 4" };
  s.years.forEach((y, i) => { const tgt = kinds[i] === "IMF projection" ? pro : act; tgt.dates.push(`${y}-07-01`); tgt.values.push(s.values[i]); });
  if (pro.values.length && act.values.length) { pro.dates.unshift(act.dates[act.dates.length - 1]); pro.values.unshift(act.values[act.values.length - 1]); }
  return [act, pro].filter(x => x.values.length); }
/** heat matrix for non-square tables; values scaled to ±scale */
function matrixHeat(rows, cols, m, o = {}) {
  const id = uid(); const scale = o.scale || 1, f = o.fmt || (v => fmt(v, 2));
  mount(() => { const el = document.getElementById(id); if (!el) return;
    const L = o.left || 150, T = o.top || 92, cw = Math.max(46, Math.min(78, (el.clientWidth - L - 10) / cols.length)), ch = 30, W = L + cols.length * cw + 6, H = T + rows.length * ch + 6;
    const col = v => { if (v == null) return "#16191e"; const a = Math.min(1, Math.abs(v) / scale); const c = v >= 0 ? [57, 135, 229] : [230, 103, 103]; return `rgba(${c[0]},${c[1]},${c[2]},${0.1 + a * 0.8})`; };
    let svg = `<svg viewBox="0 0 ${W} ${H}" style="max-width:${W}px" role="img" aria-label="${esc(o.title || "matrix")}">`;
    cols.forEach((c, j) => { svg += `<text transform="translate(${L + j * cw + cw / 2 + 4},${T - 8}) rotate(-45)" text-anchor="start">${esc(c)}</text>`; });
    rows.forEach((r, i) => { svg += `<text x="${L - 8}" y="${T + i * ch + ch / 2 + 4}" text-anchor="end">${esc(r)}</text>`;
      cols.forEach((c, j) => { const v = m[i] && m[i][j]; svg += `<rect x="${L + j * cw + 1}" y="${T + i * ch + 1}" width="${cw - 2}" height="${ch - 2}" rx="2" fill="${col(v)}" data-t="${esc(r)} vs ${esc(c)}: ${v == null ? "n/a" : esc(f(v))}"/>`;
        if (v != null) svg += `<text x="${L + j * cw + cw / 2}" y="${T + i * ch + ch / 2 + 4}" text-anchor="middle" style="fill:${Math.abs(v) / scale > 0.6 ? "#fff" : C.ink2};font-family:var(--mono);pointer-events:none">${esc(f(v))}</text>`; }); });
    el.innerHTML = svg + "</svg>";
    el.querySelectorAll("rect[data-t]").forEach(r => { r.addEventListener("mousemove", e => tipAt(e, r.dataset.t)); r.addEventListener("mouseleave", tipOff); }); });
  return `<div class="chart tw" id="${id}"></div>`;
}
function selector(pg, items, current, label) {
  return `<div class="seg" role="group" aria-label="${esc(label)}" style="flex-wrap:wrap">${items.map(([k, t]) => `<button onclick="location.hash='#/${pg.sec}/${pg.id}/${encodeURIComponent(k)}'" class="${k === current ? "on" : ""}">${esc(t)}</button>`).join("")}</div>`;
}
function selectBox(pg, items, current, label, base) {
  return `<label class="sm dim" style="display:flex;gap:8px;align-items:center">${esc(label)} <select onchange="location.hash='${base || `#/${pg.sec}/${pg.id}/`}'+encodeURIComponent(this.value)" style="background:var(--panel2);border:1px solid var(--line2);border-radius:6px;padding:5px 8px">${items.map(([k, t]) => `<option value="${esc(k)}" ${k === current ? "selected" : ""}>${esc(t)}</option>`).join("")}</select></label>`;
}
const perfCells = p => p ? [pct(p.d1), pct(p.w1), pct(p.m1), pct(p.ytd), pct(p.y1)] : ["—", "—", "—", "—", "—"];
const PERF_COLS = [{ t: "1D", n: 1 }, { t: "1W", n: 1 }, { t: "1M", n: 1 }, { t: "YTD", n: 1 }, { t: "1Y", n: 1 }];

/* ======================= MODULE 11: GLOBAL DASHBOARD ======================= */
PAGES["command/global-dashboard"] = G_(pg => {
  const g = GD(), ix = g.markets.indices.filter(i => i.perf), st = (g.fx.strength || []).filter(s => s.rank).sort((a, b) => a.rank - b.rank);
  const k = t => { const i = g.markets.indices.find(x => x.ticker === t) || g.markets.commodities.find(x => x.ticker === t) || g.markets.yields.find(x => x.ticker === t); return i && i.perf; };
  const kp = (lab, p, d = 2, unit = "") => kpi(lab, p ? `${fmt(p.last, d)}${unit}` : "—", p ? `1D ${pct(p.d1)} · 1M ${pct(p.m1)}` : "pending");
  const dxy = (g.fx.strength || []).find(s => s.ccy === "USD");
  const pickC = (code, c) => code === "PCPIPCH" ? newest(ocdY(c.key, "CP"), imfCur(code, c.iso3)) : code === "NGDP_RPCH" ? newest(qgdp(c.key), imfCur(code, c.iso3)) : newest(imfCur(code, c.iso3), imfAct(code, c.iso3));
  const cmp = (code, lab, unit) => { const rows = CTRY().map(c => [c.name, pickC(code, c)]).filter(r => r[1]); const per = [...new Set(rows.map(r => r[1].period))];
    return panel(lab, barChart(rows.map(r => r[0].replace("United ", "U. ")), rows.map(r => r[1].value), { diverging: true, height: 170, unit, fmt: v => fmt(v, 1) }) + `<div class="note">${rows.length ? (code === "PCPIPCH" ? "Latest month, y/y (OECD and national sources; IMF " + NOWY + " estimate where no monthly figure)" : code === "NGDP_RPCH" ? "Latest quarter, y/y (OECD; IMF " + NOWY + " estimate where no quarterly figure)" : `IMF estimate for ${NOWY}`) + " · periods: " + esc(per.slice(0, 4).join(", ")) : "pending"}</div>`); };
  const rates = CTRY().filter((c, i, a) => a.findIndex(x => x.bis === c.bis) === i).map(c => [c.bis === "XM" ? "Euro area" : c.name, g.rates[c.bis]?.latest]).filter(r => r[1]);
  const res = CTRY().map(c => [c.name, GD().reserves?.[c.key]?.total ? { value: GD().reserves[c.key].total.value, year: GD().reserves[c.key].total.period } : wbL("FI.RES.TOTL.CD", c.iso3)]).filter(r => r[1]);
  const fdi = CTRY().map(c => [c.name, wbL("BX.KLT.DINV.CD.WD", c.iso3)]).filter(r => r[1]);
  const ch = g.changed || {};
  return header(pg, "The world at a glance: equities, currencies, rates, inflation, growth, public finances, trade, reserves, investment, commodities and bonds.") + metaStrip(["yahoo", "oecd", "gdp_q", "reserves", "imf", "bis", "worldbank"]) +
    `<div class="g g6">${kp("S&P 500", k("^GSPC"), 0)}${kp("STOXX 600", k("^STOXX"), 1)}${kp("Nikkei 225", k("^N225"), 0)}${kp("CSI 300", k("000300.SS"), 0)}${kpi("US dollar index", dxy?.absolute ? fmt(dxy.absolute.last, 2) : "—", dxy?.absolute ? `1D ${pct(dxy.absolute.d1)} · 1M ${pct(dxy.absolute.m1)}` : "")}${kp("US 10y yield", k("^TNX"), 2, "%")}</div>
    <div class="g g-32">${panel("Global stock market performance", table([{ t: "Index" }, { t: "Last", n: 1 }, ...PERF_COLS], ix.sort((a, b) => (b.perf.d1 ?? -99) - (a.perf.d1 ?? -99)).map(i => [`<a href="#/equities/index/${i.key}">${esc(i.name)}</a>`, `<span class="num">${fmt(i.perf.last, 0)}</span>`, ...perfCells(i.perf)]), { max: 420 }), `${ix.length} of ${g.markets.indices.length} indices`, "flush")}
      ${panel("Currency strength ranking", table([{ t: "#" }, { t: "Currency" }, { t: "Score", n: 1 }, { t: "1M vs all", n: 1 }], st.map(s => [s.rank, `<a href="#/currencies/detail/${s.ccy}">${s.ccy}</a> <span class="dim sm">${esc(s.name)}</span>`, `<span class="num">${sgn(s.composite, 2)}</span>`, pct(s.scores.m1)])), `<a href="#/currencies/ranking">Detail →</a>`, "flush")}</div>
    <div class="g g3">${panel("Policy interest rates", barChart(rates.map(r => r[0].replace("United ", "U. ")), rates.map(r => r[1].value), { height: 170, unit: "%", fmt: v => fmt(v, 2), color: C.gold }) + `<div class="note">BIS, latest month per bank</div>`)}${cmp("PCPIPCH", "Inflation (average CPI, %)", "%")}${cmp("NGDP_RPCH", "Real GDP growth (%)", "%")}</div>
    <div class="g g3">${cmp("GGXCNL_NGDP", "Fiscal balance (% of GDP)", "%")}${cmp("BCA_NGDPD", "Current account (% of GDP)", "%")}${panel("Foreign reserves incl. gold", barChart(res.map(r => r[0].replace("United ", "U. ")), res.map(r => r[1].value / 1e9), { height: 170, unit: " $bn", fmt: v => fmt(v, 0), color: C.s1 }) + `<div class="note">${GD().reserves && Object.keys(GD().reserves).length ? "IMF (IRFCL), latest month: " + esc([...new Set(res.map(r => r[1].year))].slice(0, 3).join(", ")) : "World Bank · annual"}</div>`)}</div>
    <div class="g g3">${panel("Foreign direct investment, net inflows", barChart(fdi.map(r => r[0].replace("United ", "U. ")), fdi.map(r => r[1].value / 1e9), { diverging: true, height: 170, unit: " $bn", fmt: v => fmt(v, 0) }) + `<div class="note">World Bank · ${fdi[0] ? fdi[0][1].year : ""}</div>`)}
      ${panel("Commodity performance", table([{ t: "Commodity" }, { t: "Last", n: 1 }, { t: "1D", n: 1 }, { t: "1M", n: 1 }, { t: "1Y", n: 1 }], g.markets.commodities.filter(c => c.perf).map(c => [`<a href="#/commodities/detail/${c.key}">${esc(c.name)}</a>`, `<span class="num">${fmt(c.perf.last, 2)}</span>`, pct(c.perf.d1), pct(c.perf.m1), pct(c.perf.y1)]), { max: 260 }), "", "flush")}
      ${panel("Bond markets", table([{ t: "Instrument" }, { t: "Yield", n: 1 }, { t: "1M chg (pp)", n: 1 }, { t: "As of" }], [...g.markets.yields.filter(y => y.perf).map(y => [esc(y.name), `<span class="num">${fmt(y.perf.last, 2)}%</span>`, `<span class="num">${sgn(y.perf.last - y.perf.last / (1 + (y.perf.m1 || 0) / 100), 2)}</span>`, esc(y.perf.date)]),
        ...Object.entries(g.fred || {}).filter(([k2]) => k2.length === 2 && k2 !== "us").map(([k2, v]) => [`${esc(cBy(k2)?.name || k2)} 10y (monthly)`, `<span class="num">${fmt(v.latest.value, 2)}%</span>`, "", esc(v.latest.date)])]) + (Object.keys(g.fred || {}).length ? "" : `<div class="note">Non-US 10-year yields need the FRED key.</div>`), "", "flush")}</div>
    <div class="g g3">${panel("What changed today?", `<h3>Largest index moves</h3>${L((ch.index_movers || []).map(([n, v]) => `${esc(n)} ${pct(v)}`))}<h3 style="margin-top:8px">Largest commodity moves</h3>${L((ch.commodity_movers || []).map(([n, v]) => `${esc(n)} ${pct(v)}`))}<h3 style="margin-top:8px">Policy rate moves (last 2 months)</h3>${listOr(ch.rate_moves, "None recorded.")}`, `<a href="#/command/what-changed">Full report →</a>`)}
      ${panel("Major economic releases", L([...(R("calendar").events || []), ...((GD()?.calendar_feed?.events || []).filter(e => e.importance === "High" && !/FOMC Press|by County|Research |Excluding|Debt to|Ratios/.test(e.event)))].filter(e => e.date >= S.data.as_of).sort((a, b) => a.date.localeCompare(b.date)).slice(0, 8).map(e => `<span class="num">${esc(e.date)}</span> ${esc(e.event)}`), "No scheduled events."), `<a href="#/command/calendar">Calendar →</a>`)}
      ${panel("Geopolitical developments", L((R("geopolitics").items || []).map(x => `<span class="num dim">${esc(x.date)}</span> ${esc(x.headline)}`)), `<a href="#/macro/geopolitics">More →</a>`)}</div>`;
});
const _wc = PAGES["command/what-changed"];
PAGES["command/what-changed"] = pg => { const ch = GD()?.changed; const glob = ch ? `<h2 style="margin:4px 0 10px">Global markets</h2><div class="g g4">${panel("Largest index moves (1 day)", L((ch.index_movers || []).map(([n, v]) => `${esc(n)} ${pct(v)}`)))}${panel("Largest commodity moves (1 day)", L((ch.commodity_movers || []).map(([n, v]) => `${esc(n)} ${pct(v)}`)))}${panel("Central bank moves (last 2 months)", listOr(ch.rate_moves, "None recorded by BIS."))}${panel("Currency strength", `<div class="kv" style="display:grid;grid-template-columns:auto 1fr;gap:6px 12px"><span class="dim">Strongest</span><b>${esc(ch.strongest_ccy || "—")}</b><span class="dim">Weakest</span><b>${esc(ch.weakest_ccy || "—")}</b></div>`)}</div><h2 style="margin:14px 0 10px">Gold and Bitcoin</h2>` : "";
  return _wc(pg).replace(`</div></div>`, `</div></div>${glob}`); };

/* ======================= MODULE 1: ECONOMIES ======================= */
PAGES["economies/comparison"] = G_(pg => {
  const rows = CTRY().map(c => { const r = GD().rates[c.bis]?.latest; const v = (code) => imfL(code, c.iso3);
    const nc = (x, d = 1) => x ? `<span class="num">${fmt(x.value, d)}</span><div class="sm dim">${esc(x.period)}${x.kind.startsWith("IMF estimate") ? " IMF est." : ""}</div>` : "—";
    const cell = (x, d = 1) => x ? `<span class="num">${fmt(x.value, d)}</span><div class="sm dim">${x.year}${x.kind && x.kind.includes("IMF") && x.kind !== "Actual (IMF)" ? " est." : x.kind && x.kind.includes("World Bank") ? " WB" : ""}</div>` : "—";
    return [`<a href="#/economies/${c.key}"><b>${esc(c.name)}</b></a><div class="sm dim">${esc(c.ccy)} · ${esc(c.cb)}</div>`, r ? `<span class="num">${fmt(r.value, 2)}%</span><div class="sm dim">${esc(r.date)}</div>` : "—", nc(newest(qgdp(c.key), imfCur("NGDP_RPCH", c.iso3))), nc(newest(ocdY(c.key, "CP"), imfCur("PCPIPCH", c.iso3))), nc(newest(ocd(c.key, "UNEMP"), imfCur("LUR", c.iso3))), nc(newest(imfCur("GGXCNL_NGDP", c.iso3), imfAct("GGXCNL_NGDP", c.iso3))), nc(newest(imfCur("GGXWDG_NGDP", c.iso3), imfAct("GGXWDG_NGDP", c.iso3)), 0), nc(newest(imfCur("BCA_NGDPD", c.iso3), imfAct("BCA_NGDPD", c.iso3))), (rv => rv ? `${big(rv.value)}<div class="sm dim">${esc(rv.period)}</div>` : "—")(newest(GD().reserves?.[c.key]?.total ? { ...GD().reserves[c.key].total, kind: "Actual (monthly)" } : null, wbAct("FI.RES.TOTL.CD", c.iso3))), v("NGDPDPC") ? `<span class="num">$${fmt(v("NGDPDPC").value, 0)}</span>` : "—"]; });
  return header(pg, "Ten economies side by side. Germany and France share the ECB's policy rate.") + metaStrip(["imf", "bis", "worldbank"]) +
    panel("Key indicators", table([{ t: "Economy" }, { t: "Policy rate", n: 1 }, { t: "GDP growth %", n: 1 }, { t: "Inflation %", n: 1 }, { t: "Unemployment %", n: 1 }, { t: "Fiscal bal. % GDP", n: 1 }, { t: "Debt % GDP", n: 1 }, { t: "Curr. acct % GDP", n: 1 }, { t: "Reserves", n: 1 }, { t: "GDP / capita", n: 1 }], rows), "Newest reading for each: GDP growth = latest quarter y/y; inflation and unemployment = latest month (OECD); fiscal and current account = IMF estimate for the current year. Russia uses IMF figures (no OECD data).", "flush") +
    `<div class="g g2" style="margin-top:12px">${panel("Real GDP growth, history and IMF projections (%)", lineChart(CTRY().slice(0, 6).flatMap((c, i) => yrSeries(imfSer("NGDP_RPCH", c.iso3), c.name, [C.gold, C.s1, C.s2, C.s3, C.s4, C.s5][i]).slice(0, 1)), { height: 240, zero: true, unit: "%" }))}${panel("Government debt, % of GDP", lineChart(CTRY().slice(0, 6).flatMap((c, i) => yrSeries(GD().imf.GGXWDG_NGDP?.[c.iso3], c.name, [C.gold, C.s1, C.s2, C.s3, C.s4, C.s5][i]).slice(0, 1)), { height: 240, unit: "%" }))}</div>`;
});
// ---- "most recent reading" helpers: monthly/quarterly sources first, then the IMF's current-year estimate, then annual actuals
const NOWY = new Date().getUTCFullYear();
const perKey = p => { p = String(p); const q = /^(\d{4})-Q(\d)$/.exec(p); if (q) return `${q[1]}-${String(q[2] * 3).padStart(2, "0")}`; if (/^\d{4}$/.test(p)) return `${p}-12`; return p.slice(0, 7); };
const ocd = (ck, m) => { const x = GD()?.oecd?.countries?.[ck]?.[m]; return x ? { value: x.latest, period: x.period, kind: "Actual (monthly)", source: x.source || "OECD", unit: x.transform || x.unit } : null; };
const ocdY = (ck, m) => { const x = ocd(ck, m); return x && /growth rate/i.test(x.unit || "") ? x : null; };   // only a genuine y/y growth figure may fill a "y/y" row
